from pathlib import Path
import re
p=Path('E:/cxy/09-设计与原型/自定义活动管理/活动执行填报.html')
s=p.read_text(encoding='utf-8')
s=re.sub(r'<section><h2>实际执行情况（需要填写）</h2>.*?</section>','',s,flags=re.S)
s=re.sub(r'<section><h2>门店执行数据</h2>.*?</section>','',s,flags=re.S)
a=s.index('<section><h2>实际费用与承担');b=s.index('<div class="footer">',a)
s=s[:a]+'''<section><h2>实际费用填报</h2><small>申请数据不可修改，仅填写每项实际发生费用；未发生请填0。</small><div class="table-wrap"><table><thead><tr><th>费用项</th><th>申请预算（元）</th><th>实际费用（元）*</th><th>我司承担%</th><th>支付方式</th></tr></thead><tbody id="costs"></tbody></table></div><div class="summary" aria-live="polite"><div><small>申请费用总额（元）</small><b>1,746.88</b></div><div><small>实际费用总额（元）</small><b id="actual">待填写</b></div><div><small>与预算差异（元）</small><b id="difference">待填写</b></div><div><small>实际我司承担（元）</small><b id="company">待填写</b></div></div></section>'''+s[b:]
script='''(()=>{const q=s=>document.querySelector(s),money=n=>n.toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2});const items=[['团购奖励',1600],['第三方服务费',48],['发票税费',98.88]];items.forEach(([name,budget],i)=>{const tr=document.createElement('tr');tr.innerHTML='<td>'+name+'</td><td>'+money(budget)+'</td><td><input required class="amount" aria-label="'+name+'实际费用" type="number" min="0" step="0.01" placeholder="请填写"></td><td>100%</td><td>对公付款</td>';q('#costs').append(tr)});const inputs=Array.from(document.querySelectorAll('.amount'));function calc(){const complete=inputs.every(e=>e.value!==''&&e.checkValidity()),total=Math.round(inputs.reduce((sum,e)=>sum+Number(e.value),0)*100)/100;q('#actual').textContent=complete?money(total):'待填写';q('#difference').textContent=complete?(total>1746.88?'+':'')+money(total-1746.88):'待填写';q('#company').textContent=complete?money(total):'待填写';return total}inputs.forEach(el=>el.addEventListener('input',calc));const key='activity-execution-amounts-v2';try{const saved=JSON.parse(localStorage.getItem(key));if(Array.isArray(saved))inputs.forEach((el,i)=>{if(typeof saved[i]==='string')el.value=saved[i]})}catch{}q('#save').onclick=()=>{try{localStorage.setItem(key,JSON.stringify(inputs.map(e=>e.value)));q('#feedback').textContent='实际费用草稿已保存在当前浏览器。'}catch{q('#feedback').textContent='保存失败，请保留页面后重试。'}};q('#execution').onsubmit=e=>{e.preventDefault();const total=calc();q('#feedback').className=total>1746.88?'error':'';q('#feedback').textContent=total>1746.88?'实际费用超出申请预算，请先完成补充审批。':'校验通过。当前为演示页面，未提交真实数据。'};calc()})();'''
s=re.sub(r'<script>.*?</script>','<script>'+script+'</script>',s,count=1,flags=re.S)
p.write_text(s,encoding='utf-8')
